import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v
        self.nxt = nxt

def build(vals, pos):
    if not vals:
        return None
    head = N(vals[0])
    nodes = [head]
    for v in vals[1:]:
        nodes[-1].nxt = N(v)
        nodes.append(nodes[-1].nxt)
    if pos >= 0:
        nodes[-1].nxt = nodes[pos]
    return head

def cycle_start(head):
    seen = set()
    cur = head
    while cur:
        if id(cur) in seen:
            return cur.v
        seen.add(id(cur))
        cur = cur.nxt
    return -1


