import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v
        self.nxt = nxt

def build(vals, pos):
    if not vals:
        return None
    head = N(vals[0])
    nodes = [head]
