def cycle_start(head):
    slow = fast = head
    meet = None
    while fast and fast.nxt:
        slow = slow.nxt
        fast = fast.nxt.nxt
        if slow is fast:
            meet = slow
            break
    if meet is None:
        return -1
    p = head
    q = meet
    while p is not q:
        p = p.nxt
        q = q.nxt
    return p.v


